"use client";

import React, { useEffect, use } from "react";
import { useRouter } from "next/navigation";
import { useAuctionStore } from "@/stores/auction.store";
import { useAuthStore } from "@/stores/auth.store";
import { useUIStore } from "@/stores/ui.store";
import { useConnectionStore } from "@/stores/connection.store";
import { auctionService } from "@/services/auction.service";
import type { Player } from "@/types";

import { BudgetTicker } from "@/components/auction/BudgetTicker";
import { PlayerPoolSidebar } from "@/components/auction/PlayerPoolSidebar";
import { PlayerAuctionCard } from "@/components/auction/PlayerAuctionCard";
import { CurrentBid } from "@/components/auction/CurrentBid";
import { AuctionTimer } from "@/components/auction/AuctionTimer";
import { AuctionControls } from "@/components/auction/AuctionControls";
import { TeamPanel } from "@/components/auction/TeamPanel";
import { TeamQuickView } from "@/components/auction/TeamQuickView";
import { AISuggestionPanel } from "@/components/auction/AISuggestionPanel";
import { HostAuctionControls } from "@/components/auction/HostAuctionControls";
import { SoldOverlay } from "@/components/auction/SoldOverlay";
import { UnsoldOverlay } from "@/components/auction/UnsoldOverlay";
import { ConnectionStatus } from "@/components/auction/ConnectionStatus";
import { BidFeed } from "@/components/auction/BidFeed";
import { Drawer } from "@/components/ui/Drawer";
import { Button } from "@/components/ui/Button";

import { Layers, Users, Bot } from "lucide-react";

export default function LiveAuctionPage({
  params,
}: {
  params: Promise<{ roomCode: string }>;
}) {
  const resolvedParams = use(params);
  const roomCode = resolvedParams.roomCode.toUpperCase();

  const { user } = useAuthStore();
  const { status: connectionStatus, latencyMs } = useConnectionStore();
  const router = useRouter();
  const snapshot = useAuctionStore(s => s.snapshot);

  // Determine host status from auction store (authoritative from ROOM_STATE)
  const hostUserId = useAuctionStore((state) => state.snapshot?.host.userId);
  const isHost = !!user && user.id === hostUserId;

  // Navigate to results when auction completes
  const auctionStatus = useAuctionStore((state) => state.auctionStatus);


  // Auction Store selectors
  const activePlayer = useAuctionStore((state) => state.activePlayer);
  const currentBid = useAuctionStore((state) => state.currentBid);
  const highestBidder = useAuctionStore((state) => state.highestBidder);
  const endsAt = useAuctionStore((state) => state.endsAt);
  const serverTimeOffset = useAuctionStore((state) => state.serverTimeOffset);
  const minimumNextBid = useAuctionStore((state) => state.minimumNextBid);
  const currentPot = useAuctionStore((state) => state.currentPot);
  const teams = useAuctionStore((state) => state.teams);
  const recentBids = useAuctionStore((state) => state.recentBids);
  const aiSuggestion = useAuctionStore((state) => state.aiSuggestion);
  // auctionStatus already declared above for the completed-redirect effect
  const soldOverlay = useAuctionStore((state) => state.soldOverlay);
  const unsoldOverlay = useAuctionStore((state) => state.unsoldOverlay);
  const antiSnipingNotice = useAuctionStore((state) => state.antiSnipingNotice);
  const bidErrorNotice = useAuctionStore((state) => state.bidErrorNotice);

  const initAuction = useAuctionStore((state) => state.initAuction);
  const leaveAuction = useAuctionStore((state) => state.leaveAuction);
  const placeBid = useAuctionStore((state) => state.placeBid);
  const hostPause = useAuctionStore((state) => state.hostPause);
  const hostResume = useAuctionStore((state) => state.hostResume);
  const hostSkip = useAuctionStore((state) => state.hostSkip);
  const hostEnd = useAuctionStore((state) => state.hostEnd);
  const clearBidError = useAuctionStore((state) => state.clearBidError);
  const dismissSoldOverlay = useAuctionStore((state) => state.dismissSoldOverlay);
  const dismissUnsoldOverlay = useAuctionStore((state) => state.dismissUnsoldOverlay);

  // UI Store
  const {
    isTeamQuickViewOpen,
    selectedTeamId,
    closeTeamQuickView,
    isMobilePlayerDrawerOpen,
    isMobileTeamDrawerOpen,
    isMobileAIDrawerOpen,
    setMobilePlayerDrawer,
    setMobileTeamDrawer,
    setMobileAIDrawer,
  } = useUIStore();

  const playerPool = useAuctionStore(s => s.players);
  useEffect(() => {
    if (auctionStatus === "COMPLETED") router.replace(`/results/${roomCode}`);
    if (snapshot?.status === "LOBBY") router.replace(`/room/${roomCode}`);
  }, [auctionStatus, snapshot?.status, roomCode, router]);

  const userTeam = teams.find((t) => t.isCurrentUser || t.managerId === user?.id);
  const userBudget = userTeam ? userTeam.budgetRemaining : 0;
  const isUserLeading =
    highestBidder && (highestBidder.id === userTeam?.id || highestBidder.isCurrentUser);

  const selectedQuickViewTeam =
    teams.find((t) => t.id === selectedTeamId) || null;

  return (
    <div className="min-h-[calc(100vh-4rem)] flex flex-col bg-[#07090d] text-[#f8fafc] relative overflow-x-hidden">
      {!snapshot && <div className="p-4 text-center text-sm text-amber-300">{bidErrorNotice || "Synchronizing room state…"}</div>}
      {/* 1. TOP STICKY BUDGET TICKER */}
      <BudgetTicker teams={teams} currentTeamId={userTeam?.id} />

      {/* Subheader with room code, status, and mobile drawer buttons */}
      <div className="w-full bg-[#0b0e14] border-b border-[#242c3d] px-4 py-2 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <span className="font-mono text-xs font-black text-[#00ff87]">
            {roomCode}
          </span>
          <span className="text-xs text-[#64748b] hidden sm:inline">•</span>
          <span className="text-xs text-[#94a3b8] hidden sm:inline">
            Pot: <strong className="uppercase text-[#f8fafc]">{currentPot}</strong>
          </span>
        </div>

        {/* Mobile / Tablet Triggers for Drawers */}
        <div className="flex lg:hidden items-center gap-1.5">
          <Button
            variant="secondary"
            size="sm"
            onClick={() => setMobilePlayerDrawer(true)}
            leftIcon={<Layers className="w-3.5 h-3.5 text-[#00ff87]" />}
          >
            Players
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={() => setMobileTeamDrawer(true)}
            leftIcon={<Users className="w-3.5 h-3.5 text-sky-400" />}
          >
            Teams
          </Button>
          <Button
            variant="secondary"
            size="sm"
            onClick={() => setMobileAIDrawer(true)}
            leftIcon={<Bot className="w-3.5 h-3.5 text-purple-400" />}
          >
            AI
          </Button>
        </div>

        <div className="flex items-center gap-2">
          <ConnectionStatus status={connectionStatus} latencyMs={latencyMs} />
        </div>
      </div>

      {/* Host Bar if current user is room host */}
      {isHost && (
        <div className="px-4 py-1.5 bg-[#080a0f] border-b border-[#242c3d]">
          <HostAuctionControls
            isPaused={auctionStatus === "PAUSED"}
            onPause={hostPause}
            onResume={hostResume}
            onSkip={hostSkip}
            onEnd={hostEnd}
            hasActivePlayer={!!activePlayer}
            hasBid={!!highestBidder}
            synced={connectionStatus === "SYNCED"}
            canRecall={!activePlayer && snapshot?.playerQueue.length === 0 && !!snapshot?.unsoldPlayers.length}
            onRecall={() => { void useAuctionStore.getState().hostCommand("START_RECALL").catch(() => {}); }}
          />
        </div>
      )}

      {/* 2. MAIN 3-COLUMN AUCTION LAYOUT */}
      <div className="flex-1 max-w-[1600px] w-full mx-auto p-3 sm:p-4 grid grid-cols-1 lg:grid-cols-12 gap-4 items-start">
        {/* LEFT COLUMN: Pot / Player Pool Sidebar (Hidden on mobile/tablet, available via Drawer) */}
        <div className="hidden lg:block lg:col-span-3 h-[calc(100vh-10rem)] sticky top-28">
          <PlayerPoolSidebar
            players={playerPool}
            activePlayerId={activePlayer?.id}
            currentPot={currentPot}
          />
        </div>

        {/* CENTER COLUMN: Player Card & Live Auction Console */}
        <div className="lg:col-span-6 space-y-4 max-w-xl mx-auto w-full">
          {/* Player Card */}
          <PlayerAuctionCard player={activePlayer} />

          {/* Current Bid & Timer in 2-column on center */}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <CurrentBid
              currentBid={currentBid}
              highestBidder={highestBidder}
              currentTeamId={userTeam?.id}
            />

            <AuctionTimer
              endsAt={endsAt}
              serverTimeOffset={serverTimeOffset}
              isPaused={auctionStatus === "PAUSED"}
              remainingTimeMs={snapshot?.remainingTimeMs ?? null}
              synced={connectionStatus === "SYNCED"}
            />
          </div>

          {/* Bid Button & Custom Controls */}
          <AuctionControls
            minimumNextBid={minimumNextBid}
            currentBid={currentBid}
            userBudgetRemaining={userBudget}
            isUserLeading={!!isUserLeading}
            isPaused={auctionStatus === "PAUSED"}
            onPlaceBid={placeBid}
            disabled={connectionStatus !== "SYNCED" || !activePlayer || !snapshot?.biddingOpen}
            maximumPermittedBid={snapshot?.maximumPermittedBidCr ?? 0}
            allowCustomBids={snapshot?.settings.allowCustomBids ?? false}
            antiSnipingNotice={antiSnipingNotice}
            bidErrorNotice={bidErrorNotice}
            onClearError={clearBidError}
          />

          {/* Live Recent Bids Feed */}
          <BidFeed bids={recentBids} />
        </div>

        {/* RIGHT COLUMN: Teams & AI Assistant (Hidden on mobile/tablet, available via Drawer) */}
        <div className="hidden lg:flex lg:col-span-3 flex-col gap-4 h-[calc(100vh-10rem)] sticky top-28">
          <div className="flex-1 overflow-hidden min-h-[300px]">
            <TeamPanel teams={teams} currentTeamId={userTeam?.id} />
          </div>

          <div className="shrink-0">
            <AISuggestionPanel suggestion={aiSuggestion} />
          </div>
        </div>
      </div>

      {/* 3. DRAWERS & MODALS FOR RESPONSIVE EXPERIENCE */}

      {/* Team Quick View Drawer */}
      <TeamQuickView
        isOpen={isTeamQuickViewOpen}
        onClose={closeTeamQuickView}
        team={selectedQuickViewTeam}
        roomCode={roomCode}
      />

      {/* Mobile Players Drawer */}
      <Drawer
        isOpen={isMobilePlayerDrawerOpen}
        onClose={() => setMobilePlayerDrawer(false)}
        position="bottom"
        title="POT & PLAYER POOL"
      >
        <div className="h-[60vh]">
          <PlayerPoolSidebar
            players={playerPool}
            activePlayerId={activePlayer?.id}
            currentPot={currentPot}
          />
        </div>
      </Drawer>

      {/* Mobile Teams Drawer */}
      <Drawer
        isOpen={isMobileTeamDrawerOpen}
        onClose={() => setMobileTeamDrawer(false)}
        position="bottom"
        title="FRANCHISE PURSES & ROSTERS"
      >
        <div className="h-[60vh]">
          <TeamPanel teams={teams} currentTeamId={userTeam?.id} />
        </div>
      </Drawer>

      {/* Mobile AI Assistant Drawer */}
      <Drawer
        isOpen={isMobileAIDrawerOpen}
        onClose={() => setMobileAIDrawer(false)}
        position="bottom"
        title="AI AUCTION VALUATION"
      >
        <div className="p-2">
          <AISuggestionPanel suggestion={aiSuggestion} />
        </div>
      </Drawer>

      {/* 4. OVERLAYS */}
      <SoldOverlay soldData={soldOverlay} onDismiss={dismissSoldOverlay} />
      <UnsoldOverlay unsoldData={unsoldOverlay} onDismiss={dismissUnsoldOverlay} />
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { useRouter } from "next/navigation";
import { useRoomStore } from "@/stores/room.store";
import { useAuthStore } from "@/stores/auth.store";
import { RoomSettings } from "@/types";

export default function CreateRoomPage() {
  const router = useRouter();
  const { createRoom, isLoading: storeLoading, error: storeError } = useRoomStore();
  const { user } = useAuthStore();

  const [formData, setFormData] = useState<RoomSettings>({
    auctionName: "Super League Football Auction 2026",
    numberOfTeams: 6,
    startingBudget: 200,
    minSquadSize: 11,
    maxSquadSize: 18,
    playerTimerSeconds: 15,
    antiSnipingEnabled: true,
    antiSnipingThresholdSeconds: 5,
    timerResetDurationSeconds: 6,
    minPlayerBasePrice: 5,
    playerPoolSource: "default",
    filters: {
      minOvr: 84,
      maxOvr: 93,
      gkCount: 6,
      defCount: 16,
      midCount: 20,
      attCount: 18,
    },
  });

  const [validationError, setValidationError] = useState<string | null>(null);
  const [sourceNotice, setSourceNotice] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSourceSelect = (source: "default" | "csv" | "custom") => {
    if (source !== 'default') {setSourceNotice('Only the configured server player catalog is available.'); return;}
    setFormData(prev => ({...prev, playerPoolSource: source})); setSourceNotice(null);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    if (!formData.auctionName.trim()) {
      setValidationError("Auction Room Name is required.");
      return;
    }
    if (formData.numberOfTeams < 2 || formData.numberOfTeams > 16) {
      setValidationError("Number of teams must be between 2 and 16.");
      return;
    }
    if (formData.startingBudget < 10) {
      setValidationError("Starting budget must be at least ₹10 Cr.");
      return;
    }
    if (formData.minSquadSize > formData.maxSquadSize) {
      setValidationError("Min squad size cannot exceed max squad size.");
      return;
    }
    if (formData.startingBudget < formData.minSquadSize * formData.minPlayerBasePrice) {
      setValidationError(
        `Starting budget (₹${formData.startingBudget} Cr) cannot fund minimum squad (${formData.minSquadSize} × ₹${formData.minPlayerBasePrice} Cr = ₹${
          formData.minSquadSize * formData.minPlayerBasePrice
        } Cr).`
      );
      return;
    }
    if (
      formData.antiSnipingEnabled &&
      formData.timerResetDurationSeconds < formData.antiSnipingThresholdSeconds
    ) {
      setValidationError("Timer extension duration must be greater than or equal to trigger threshold.");
      return;
    }

    try {
      setIsSubmitting(true);
      const roomCode = await createRoom(formData);
      if (roomCode) {
        router.push(`/room/${roomCode}`);
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to create room.";
      setValidationError(msg);
    } finally {
      setIsSubmitting(false);
    }
  };

  const activeLoading = isSubmitting || storeLoading;
  const displayError = validationError || storeError;

  return (
    <div className="flex-1 w-full min-h-[calc(100vh-58px)] grid grid-cols-1 lg:grid-cols-[1.12fr_1fr]">
      {/* LEFT COLUMN: Immersive Football Visual & Value Propositions (Full-bleed from left screen edge to form) */}
      <section className="relative w-full min-h-[620px] lg:min-h-full overflow-hidden flex flex-col justify-between p-6 sm:p-10 lg:pl-12 lg:pr-8 xl:pl-16 xl:pr-10 2xl:pl-20 py-8 xl:py-12">
        {/* Full-bleed Brighter Background Image Layer */}
        <div
          className="absolute inset-0 bg-cover bg-no-repeat pointer-events-none"
          style={{
            backgroundImage: "url('/images/create-room-left.png')",
            backgroundPosition: "center center",
            filter: "brightness(1.22) contrast(1.08)",
          }}
        />

        {/* Controlled Directional Gradient: Darker on left where text lives, translucent on right where stadium & football are */}
        <div
          className="absolute inset-0 pointer-events-none"
          style={{
            background:
              "linear-gradient(90deg, rgba(2, 13, 21, 0.72) 0%, rgba(2, 13, 21, 0.48) 42%, rgba(2, 13, 21, 0.16) 72%, rgba(2, 13, 21, 0.04) 100%), linear-gradient(180deg, rgba(2, 13, 21, 0.20) 0%, transparent 45%, rgba(2, 13, 21, 0.65) 100%)",
          }}
        />

        {/* Soft Ambient Neon Glow */}
        <div className="absolute -left-20 top-1/4 w-96 h-96 bg-[#00F5A0]/10 rounded-full blur-3xl pointer-events-none" />

        {/* Left Top / Middle Content Area */}
        <div className="relative z-10 space-y-6 max-w-xl">
          {/* Eyebrow Tag */}
          <div className="inline-flex items-center space-x-2">
            <span className="text-[11px] font-bold tracking-[0.25em] text-[#22BDF6] uppercase">
              CREATE AUCTION ROOM
            </span>
          </div>

          {/* Giant Typography Headline */}
          <h1 className="text-4xl sm:text-5xl xl:text-[54px] font-black uppercase tracking-tight leading-[1.03] text-white drop-shadow-md">
            YOUR LEAGUE.
            <br />
            YOUR RULES.
            <br />
            <span className="text-[#00F5A0] drop-shadow-[0_0_20px_rgba(0,245,160,0.4)]">
              BIGGER GAMES.
            </span>
          </h1>

          {/* Subtitle Paragraph */}
          <p className="text-sm sm:text-base text-[#9EB3C7] font-normal leading-relaxed max-w-lg">
            Set up your auction. Invite your friends. Build your dream squad and create unforgettable football battles.
          </p>

          {/* 4 Key Feature Badges Strip */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-4">
            {/* Feature 1 */}
            <div className="flex flex-col space-y-1.5 p-2 rounded-lg bg-[#081725]/40 border border-[#22BDF6]/10 backdrop-blur-sm">
              <div className="w-8 h-8 rounded-md bg-[#00F5A0]/10 border border-[#00F5A0]/30 flex items-center justify-center text-[#00F5A0]">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path
                    d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0zm6 3a2 2 0 11-4 0 2 2 0 014 0zM7 10a2 2 0 11-4 0 2 2 0 014 0z"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  ></path>
                </svg>
              </div>
              <span className="text-[11px] font-bold text-white uppercase tracking-wider">
                CUSTOM BUDGETS
              </span>
              <span className="text-[10px] text-[#7E92A5] leading-tight">
                Set your spending limits
              </span>
            </div>

            {/* Feature 2 */}
            <div className="flex flex-col space-y-1.5 p-2 rounded-lg bg-[#081725]/40 border border-[#22BDF6]/10 backdrop-blur-sm">
              <div className="w-8 h-8 rounded-md bg-[#00F5A0]/10 border border-[#00F5A0]/30 flex items-center justify-center text-[#00F5A0]">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path
                    d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  ></path>
                </svg>
              </div>
              <span className="text-[11px] font-bold text-white uppercase tracking-wider">
                SQUAD CONTROL
              </span>
              <span className="text-[10px] text-[#7E92A5] leading-tight">
                Define team size &amp; roles
              </span>
            </div>

            {/* Feature 3 */}
            <div className="flex flex-col space-y-1.5 p-2 rounded-lg bg-[#081725]/40 border border-[#22BDF6]/10 backdrop-blur-sm">
              <div className="w-8 h-8 rounded-md bg-[#00F5A0]/10 border border-[#00F5A0]/30 flex items-center justify-center text-[#00F5A0]">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <path
                    d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  ></path>
                </svg>
              </div>
              <span className="text-[11px] font-bold text-white uppercase tracking-wider">
                ANTI-SNIPING
              </span>
              <span className="text-[10px] text-[#7E92A5] leading-tight">
                Fair and competitive
              </span>
            </div>

            {/* Feature 4 */}
            <div className="flex flex-col space-y-1.5 p-2 rounded-lg bg-[#081725]/40 border border-[#22BDF6]/10 backdrop-blur-sm">
              <div className="w-8 h-8 rounded-md bg-[#00F5A0]/10 border border-[#00F5A0]/30 flex items-center justify-center text-[#00F5A0]">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <circle cx="12" cy="12" r="9"></circle>
                  <path d="M12 6v6l4 2" strokeLinecap="round" strokeLinejoin="round"></path>
                </svg>
              </div>
              <span className="text-[11px] font-bold text-white uppercase tracking-wider">
                REAL-TIME ACTION
              </span>
              <span className="text-[10px] text-[#7E92A5] leading-tight">
                Keep the game exciting
              </span>
            </div>
          </div>
        </div>

        {/* Left Bottom Slogan & Motivational Quote */}
        <div className="relative z-10 pt-10 flex items-end justify-between">
          {/* Handwritten Script Callout */}
          <div className="transform -rotate-6 select-none">
            <p className="font-script text-3xl sm:text-4xl text-white tracking-wide leading-none drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)]">
              Bid
              <br />
              Build
              <br />
              <span className="relative inline-block text-white">
                Dominate
                <span className="absolute left-0 bottom-[-4px] w-full h-[4px] bg-[#00F5A0] rounded-full shadow-[0_0_8px_#00F5A0]"></span>
              </span>
            </p>
          </div>

          {/* Locker Tunnel Inscription Quote */}
          <div className="text-right hidden sm:block opacity-35 max-w-[160px]">
            <p className="text-[13px] font-black uppercase tracking-wider text-slate-300 leading-tight">
              GREAT MANAGERS BUILD GREAT STORIES
            </p>
          </div>
        </div>
      </section>

      {/* RIGHT COLUMN: Auction Configuration Form (Directly adjacent to Left Hero) */}
      <section className="w-full p-4 sm:p-6 lg:p-8 xl:p-12 flex flex-col justify-center bg-[#020D15]/85 backdrop-blur-md border-l border-[rgba(95,135,164,0.12)]">
        <form className="space-y-4 max-w-[760px] mx-auto w-full" onSubmit={handleSubmit}>
          {/* Feedback / Alert Notice */}
          {displayError && (
            <div className="rounded-lg bg-red-950/40 border border-red-500/50 p-3 text-xs text-red-200 flex items-center justify-between animate-notice">
              <div className="flex items-center space-x-2">
                <svg className="w-4 h-4 text-red-400 shrink-0" fill="none" stroke="currentColor" strokeWidth="2" viewBox="0 0 24 24">
                  <circle cx="12" cy="12" r="9"></circle>
                  <line x1="12" y1="8" x2="12" y2="12"></line>
                  <line x1="12" y1="16" x2="12.01" y2="16"></line>
                </svg>
                <span>{displayError}</span>
              </div>
              <button
                type="button"
                onClick={() => setValidationError(null)}
                className="text-red-400 hover:text-white text-sm font-bold ml-2"
              >
                ✕
              </button>
            </div>
          )}

          {sourceNotice && (
            <div className="rounded-lg bg-cyan-950/40 border border-[#22BDF6]/40 p-2.5 text-xs text-cyan-200 flex items-center justify-between">
              <span>{sourceNotice}</span>
              <button
                type="button"
                onClick={() => setSourceNotice(null)}
                className="text-cyan-400 hover:text-white text-xs font-bold ml-2"
              >
