"use client";

import React, { useState, useEffect, Suspense } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { useRoomStore } from "@/stores/room.store";
import { useAuthStore } from "@/stores/auth.store";
import { Button, Input, Toast } from "@/components/ui";
import { LogIn, Hash, Shield, Sparkles, ArrowRight } from "lucide-react";

function JoinRoomForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const initialCode = searchParams.get("code") || "";

  const { joinRoom, isLoading, error, clearError } = useRoomStore();
  const { user } = useAuthStore();

  const [roomCode, setRoomCode] = useState(initialCode);
  const [teamName, setTeamName] = useState(user?.defaultTeamName || "");
  const [teamLogo, setTeamLogo] = useState(user?.defaultTeamLogo || "⚡");
  const [validationError, setValidationError] = useState<string | null>(null);

  useEffect(() => {
    if (user?.defaultTeamName && !teamName) {
      setTeamName(user.defaultTeamName);
    }
  }, [user, teamName]);

  const teamLogos = ["⚡", "🐅", "🦅", "⚔️", "☄️", "💎", "🦁", "🔴", "🐺", "🛡️"];

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    clearError();
    setValidationError(null);

    const cleanCode = roomCode.trim().toUpperCase();
    if (!cleanCode) {
      setValidationError("Please enter a room code.");
      return;
    }
    if (!teamName.trim()) {
      setValidationError("Please enter your team franchise name.");
      return;
    }

    const success = await joinRoom({
      roomCode: cleanCode,
      teamName: teamName.trim(),
      teamLogo,
    });

    if (success) {
      router.push(`/room/${cleanCode}`);
    }
  };

  return (
    <div className="w-full max-w-md mx-auto rounded-3xl bg-[#0e121a] border border-[#242c3d] p-7 shadow-2xl space-y-6">
      <div className="text-center">
        <div className="inline-flex h-12 w-12 items-center justify-center rounded-2xl bg-sky-500/15 text-sky-400 border border-sky-500/30 mb-3 shadow-[0_0_20px_rgba(56,189,248,0.2)]">
          <LogIn className="w-6 h-6" />
        </div>
        <h1 className="text-2xl font-black uppercase tracking-tight text-[#f8fafc]">
          JOIN AUCTION ROOM
        </h1>
        <p className="text-xs text-[#94a3b8] mt-1">
          Enter the invite room code and stake your franchise in the draft lobby
        </p>
      </div>

      {(error || validationError) && (
        <Toast
          type="error"
          title="Room Entry Notice"
          message={validationError || error || ""}
          onClose={() => {
            clearError();
            setValidationError(null);
          }}
        />
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        <Input
          label="Auction Room Code"
          placeholder="e.g. ABC234"
          value={roomCode}
          onChange={(e) => setRoomCode(e.target.value.toUpperCase())}
          leftIcon={<Hash className="w-4 h-4 text-sky-400" />}
          className="font-mono uppercase font-black tracking-wider text-base"
          required
        />

        <Input
          label="Your Franchise / Team Name"
          placeholder="e.g. Howrah Tigers"
          value={teamName}
          onChange={(e) => setTeamName(e.target.value)}
          leftIcon={<Shield className="w-4 h-4 text-[#00ff87]" />}
          helperText="Prefilled from your default manager profile"
          required
        />

        <div>
          <label className="block text-xs font-semibold uppercase tracking-wider text-[#94a3b8] mb-1.5">
            Select Franchise Crest
          </label>
          <div className="flex items-center gap-2 overflow-x-auto p-1 scrollbar-none">
            {teamLogos.map((emoji) => (
              <button
                key={emoji}
                type="button"
                onClick={() => setTeamLogo(emoji)}
                className={`w-10 h-10 rounded-xl border flex items-center justify-center text-xl transition-all ${
                  teamLogo === emoji
                    ? "bg-[#00ff87]/20 border-[#00ff87] shadow-[0_0_12px_rgba(0,255,135,0.3)] scale-105"
                    : "bg-[#151a24] border-[#242c3d] text-[#cbd5e1] hover:border-[#37435e]"
                }`}
              >
                {emoji}
              </button>
            ))}
          </div>
        </div>

        <div className="pt-2">
          <Button
            type="submit"
            variant="stadium"
            size="lg"
            className="w-full font-black tracking-wider text-xs py-3.5"
            isLoading={isLoading}
            rightIcon={<ArrowRight className="w-4 h-4" />}
          >
            JOIN ROOM LOBBY
          </Button>
        </div>
      </form>


    </div>
  );
}

export default function JoinPage() {
  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4 py-12 pitch-radial-grid">
      <Suspense fallback={<div className="text-center text-xs text-[#64748b]">Loading join portal...</div>}>
        <JoinRoomForm />
      </Suspense>
    </div>
  );
}

"use client";

import React, { useEffect, useState } from "react";
import { useAuthStore } from "@/stores/auth.store";
import { profileService } from "@/services/profile.service";
import {
  Achievement,
  AuctionHistoryRecord,
  User,
  UserCareerStats,
} from "@/types";
import { ProfileHeader } from "@/components/profile/ProfileHeader";
import { ProfileStats } from "@/components/profile/ProfileStats";
import { AchievementGrid } from "@/components/profile/AchievementGrid";
import { AuctionHistory } from "@/components/profile/AuctionHistory";
import { Skeleton } from "@/components/ui/Skeleton";
import { authService } from "@/services/auth.service";

export default function ProfilePage() {
  const { user, setUser } = useAuthStore();
  const [loadError, setLoadError] = useState<string | null>(null);
  const [stats, setStats] = useState<UserCareerStats | null>(null);
  const [achievements, setAchievements] = useState<Achievement[]>([]);
  const [history, setHistory] = useState<AuctionHistoryRecord[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    async function loadProfileData() {
      try {
        const [careerStats, achievementList, historyList, profile] = await Promise.all([
          profileService.getCareerStats(),
          profileService.getAchievements(),
          profileService.getAuctionHistory(),
          profileService.getProfile(),
        ]);
        setStats(careerStats);
        setUser(profile);
        setAchievements(achievementList);
        setHistory(historyList);
      } catch (err) {
        setLoadError(err instanceof Error ? err.message : "Unable to load your profile.");
      } finally {
        setIsLoading(false);
      }
    }
    loadProfileData();
  }, []);

  const activeUser = user;

  const handleProfileUpdate = async (updated: Partial<User>) => {
    const newProfile = await profileService.updateProfile(updated);
    setUser(newProfile);
  };

  if (isLoading || !activeUser) {
    return (
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-10 space-y-6">
        <Skeleton className="h-44 w-full rounded-2xl" />
        <Skeleton className="h-64 w-full rounded-2xl" />
        <Skeleton className="h-64 w-full rounded-2xl" />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8 sm:py-10 space-y-8">
      {loadError && <p role="alert" className="text-amber-300">{loadError}</p>}
      <ProfileHeader user={activeUser} onUpdate={handleProfileUpdate} />

      {stats && <ProfileStats stats={stats} />}

      <AchievementGrid achievements={achievements} />

      <AuctionHistory history={history} />
    </div>
  );
}

"use client";

import React, { useEffect, use } from "react";
import { useRouter } from "next/navigation";
import { useRoomStore } from "@/stores/room.store";
import { useAuthStore } from "@/stores/auth.store";

import { RoomHeader } from "@/components/room/RoomHeader";
import { TeamLobbyCard } from "@/components/room/TeamLobbyCard";
import { AuctionSettingsSummary } from "@/components/room/AuctionSettingsSummary";
import { HostControls } from "@/components/room/HostControls";
import { Skeleton } from "@/components/ui/Skeleton";
import { ErrorState } from "@/components/ui/ErrorState";
import { useAuctionStore } from "@/stores/auction.store";
import { useConnectionStore } from "@/stores/connection.store";
import { webSocketService } from "@/services/websocket.service";
import { ConnectionStatus } from "@/components/auction/ConnectionStatus";
import { Users } from "lucide-react";

export default function RoomLobbyPage({
  params,
}: {
  params: Promise<{ roomCode: string }>;
}) {
  const resolvedParams = use(params);
  const roomCode = resolvedParams.roomCode.toUpperCase();
  const router = useRouter();

  const { room, isHost, isLoading, error, fetchRoom } = useRoomStore();
  const { user } = useAuthStore();

  const snapshot = useAuctionStore(s => s.snapshot);
  const liveError = useAuctionStore(s => s.bidErrorNotice);
  const status = useConnectionStore(s => s.status);
  useEffect(() => {
    if (snapshot?.status === 'RUNNING' || snapshot?.status === 'PAUSED') router.replace(`/auction/${roomCode}`);
    if (snapshot?.status === 'COMPLETED') router.replace(`/results/${roomCode}`);
  }, [snapshot?.status, roomCode, router]);
  const handleStartAuction = () => { void useAuctionStore.getState().hostCommand('START_AUCTION').catch(() => {}); };

  if (isLoading || (!room && !liveError)) {
    return (
      <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-10 space-y-6">
        <Skeleton className="h-24 w-full rounded-2xl" />
        <Skeleton className="h-56 w-full rounded-2xl" />
        <Skeleton className="h-64 w-full rounded-2xl" />
      </div>
    );
  }

  if (error || liveError || !room) {
    return (
      <div className="mx-auto max-w-xl px-4 py-20">
        <ErrorState
          title="Room Not Found"
          message={error || liveError || `Unable to connect to room "${roomCode}".`}
          onRetry={() => { useAuctionStore.getState().leaveAuction(); useAuctionStore.getState().initAuction(roomCode); }}
        />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-7xl px-4 sm:px-6 lg:px-8 py-8 sm:py-10 space-y-6">
      <RoomHeader
        name={room.name}
        roomCode={room.roomCode}
        isHost={isHost}
        connected={status === "SYNCED"}
      />

      <HostControls
        isHost={isHost}
        totalTeams={room.teams.length}
        expectedTeams={room.settings.numberOfTeams}
        onStartAuction={handleStartAuction}
        disabled={status !== "SYNCED" || room.teams.length < (snapshot?.settings.minimumParticipants ?? 2)}
      />

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-7 space-y-4">
          <div className="flex items-center justify-between pb-2 border-b border-[#242c3d]">
            <div className="flex items-center gap-2">
              <Users className="w-4 h-4 text-[#00ff87]" />
              <h2 className="text-xs font-bold uppercase tracking-wider text-[#94a3b8]">
                REGISTERED FRANCHISES ({room.teams.length} / {room.settings.numberOfTeams})
              </h2>
            </div>
          </div>

          <div className="space-y-3">
            {room.teams.map((team) => (
              <TeamLobbyCard
                key={team.id}
                team={team}
                isHost={isHost}
                onRemove={() => { void webSocketService.send({ type: "KICK_MEMBER", payload: { roomCode, targetTeamId: team.id } }).catch(e => useAuctionStore.setState({ bidErrorNotice: e.message })); }}
              />
            ))}
          </div>
        </div>

        <div className="lg:col-span-5 space-y-6">
          <AuctionSettingsSummary settings={room.settings} />
        </div>
      </div>
    </div>
  );
}

"use client";

import React, { useState } from "react";
import { formatCr } from "@/lib/utils";
import { Button } from "@/components/ui/Button";
import { Modal } from "@/components/ui/Modal";
import { Input } from "@/components/ui/Input";
import { AntiSnipingNotice } from "@/stores/auction.store";
import { Zap, Clock, AlertCircle, Edit3, ArrowUpCircle } from "lucide-react";

export interface AuctionControlsProps {
  disabled?: boolean;
  maximumPermittedBid: number;
  allowCustomBids: boolean;
  minimumNextBid: number;
  currentBid: number;
  userBudgetRemaining: number;
  isUserLeading: boolean;
  isPaused: boolean;
  onPlaceBid: (amount: number) => void;
  antiSnipingNotice: AntiSnipingNotice | null;
  bidErrorNotice: string | null;
  onClearError: () => void;
}

export const AuctionControls: React.FC<AuctionControlsProps> = ({
  disabled = false, maximumPermittedBid, allowCustomBids,
  minimumNextBid,
  currentBid,
  userBudgetRemaining,
  isUserLeading,
  isPaused,
  onPlaceBid,
  antiSnipingNotice,
  bidErrorNotice,
  onClearError,
}) => {
  const [isCustomModalOpen, setIsCustomModalOpen] = useState(false);
  const [customBidValue, setCustomBidValue] = useState("");
  const [customError, setCustomError] = useState<string | null>(null);

  // Use backend provided minimumNextBid as source of truth
  const nextBidAmount = minimumNextBid;
  const canAfford = maximumPermittedBid >= nextBidAmount && nextBidAmount > 0;

  const handleInstantBid = () => {
    onClearError();
    onPlaceBid(nextBidAmount);
  };

  const handleCustomBidSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setCustomError(null);
    const parsed = parseFloat(customBidValue);

    if (!Number.isFinite(parsed) || !Number.isSafeInteger(parsed * 2) || parsed < nextBidAmount) {
      setCustomError(`Use ₹0.5 Cr steps; bid must be at least ${formatCr(nextBidAmount)}`);
      return;
    }
    if (parsed > maximumPermittedBid) {
      setCustomError(
        `Insufficient purse! You have only ${formatCr(userBudgetRemaining)} remaining.`
      );
      return;
    }

    onPlaceBid(parsed);
    setIsCustomModalOpen(false);
    setCustomBidValue("");
  };

  return (
    <div className="w-full space-y-3">
      {/* Anti-Sniping Notification Banner */}
      {antiSnipingNotice?.active && (
        <div className="flex items-center justify-center gap-2 rounded-xl bg-amber-500/15 border border-amber-500/40 p-2 text-xs font-bold text-amber-300 animate-notice shadow-[0_0_15px_rgba(245,158,11,0.2)]">
          <Clock className="w-4 h-4 animate-spin shrink-0 text-amber-400" />
          <span>TIME EXTENDED: {antiSnipingNotice.message}</span>
        </div>
      )}

      {/* Bid Error Banner */}
      {bidErrorNotice && (
        <div className="flex items-center justify-between rounded-xl bg-red-950/50 border border-red-500/50 p-3 text-xs text-red-300 animate-notice">
          <div className="flex items-center gap-2">
            <AlertCircle className="w-4 h-4 shrink-0 text-[#ef4444]" />
            <span>{bidErrorNotice}</span>
          </div>
          <button
            onClick={onClearError}
            className="text-red-400 hover:text-white font-mono text-xs ml-2"
          >
            ✕
          </button>
        </div>
      )}

      {/* Action Buttons Row */}
      <div className="flex flex-col sm:flex-row items-center gap-3">
        {/* Primary Instant Bid Button */}
        <Button
          variant="stadium"
          size="xl"
          onClick={handleInstantBid}
          disabled={disabled || isPaused || !canAfford || isUserLeading}
          className="w-full flex-1 py-4 text-lg font-black tracking-wider group"
          leftIcon={<Zap className="w-5 h-5 fill-current text-[#08090d] group-hover:scale-110 transition-transform" />}
        >
          {disabled ? ("WAITING FOR LIVE STATE") : isUserLeading ? (
            "YOU ARE HIGHEST BIDDER"
          ) : !canAfford ? (
            "INSUFFICIENT BUDGET"
          ) : isPaused ? (
            "AUCTION PAUSED"
          ) : (
            `BID ${formatCr(nextBidAmount).toUpperCase()}`
          )}
        </Button>

        {/* Custom Bid Trigger */}
        <Button
          variant="secondary"
          size="lg"
          onClick={() => {
            setCustomBidValue(nextBidAmount.toString());
            setIsCustomModalOpen(true);
          }}
          disabled={disabled || !allowCustomBids || isPaused || !canAfford || isUserLeading}
          className="w-full sm:w-auto px-5 py-4 text-xs font-bold uppercase tracking-wider"
          leftIcon={<Edit3 className="w-4 h-4" />}
        >
          Custom Bid
        </Button>
      </div>

      {/* Helper text showing remaining budget and user state */}
      <div className="flex items-center justify-between px-1 text-[11px] text-[#64748b]">
        <span>
          Next minimum valid increment:{" "}
          <strong className="text-[#cbd5e1] font-mono">
            {formatCr(nextBidAmount)}
          </strong>
        </span>
        <span>
          Your Remaining Purse:{" "}
          <strong className="text-[#00ff87] font-mono font-bold">
            {formatCr(userBudgetRemaining)}
          </strong>
        </span>
      </div>

      <p className="text-[10px] text-[#64748b]">Bid steps: below ₹10 Cr +₹0.5; ₹10–20 Cr +₹1; ₹20 Cr+ +₹2. Maximum permitted: {formatCr(maximumPermittedBid)}</p>
      {/* Custom Bid Modal */}
      <Modal
        isOpen={isCustomModalOpen}
        onClose={() => setIsCustomModalOpen(false)}
        title="Place Custom Bid"
        description={`Must be greater than or equal to ${formatCr(nextBidAmount)}`}
        maxWidth="sm"
      >
        <form onSubmit={handleCustomBidSubmit} className="space-y-4">
          <Input
            label="Bid Amount (in ₹ Cr)"
            type="number"
            step="0.5"
            min={nextBidAmount}
            max={maximumPermittedBid}
            value={customBidValue}
            onChange={(e) => setCustomBidValue(e.target.value)}
            error={customError || undefined}
            leftIcon={<span className="text-sm font-bold font-mono">₹</span>}
            rightElement={<span className="text-xs font-bold text-[#64748b]">CR</span>}
            autoFocus
            required
          />

          <div className="flex items-center justify-between text-xs text-[#94a3b8]">
            <span>Your purse limit:</span>
            <span className="font-mono font-bold text-[#00ff87]">
              {formatCr(userBudgetRemaining)}
            </span>
          </div>

          <div className="flex items-center justify-end gap-2 pt-2 border-t border-[#242c3d]">
            <Button
              type="button"
              variant="ghost"
              size="sm"
              onClick={() => setIsCustomModalOpen(false)}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              variant="primary"
              size="sm"
              rightIcon={<ArrowUpCircle className="w-4 h-4" />}
            >
              Confirm Bid
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

"use client";

import React from "react";
import { ConnectionStateStatus } from "@/stores/connection.store";
import { Wifi, WifiOff, RefreshCw } from "lucide-react";

export interface ConnectionStatusProps {
  status: ConnectionStateStatus;
  latencyMs?: number | null;
}

export const ConnectionStatus: React.FC<ConnectionStatusProps> = ({
  status,
  latencyMs,
}) => {
  if (status === "SYNCED") {
    return (
      <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-[#00ff87]/10 border border-[#00ff87]/30 text-[#00ff87] text-[11px] font-mono select-none">
        <span className="w-2 h-2 rounded-full bg-[#00ff87] shadow-[0_0_8px_#00ff87]" />
        <span className="font-bold">LIVE SYNC</span>
        {latencyMs && <span className="text-[#64748b]">{latencyMs}ms</span>}
      </div>
    );
  }

  if (status === "RECONNECTING" || status === "CONNECTING" || status === "CONNECTED") {
    return (
      <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-amber-500/15 border border-amber-500/40 text-amber-300 text-[11px] font-mono animate-pulse select-none">
        <RefreshCw className="w-3 h-3 animate-spin text-amber-400" />
        <span className="font-bold">{status === "RECONNECTING" ? "RECONNECTING…" : "SYNCHRONIZING…"}</span>
      </div>
    );
  }

  return (
    <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-red-500/15 border border-red-500/40 text-red-400 text-[11px] font-mono select-none">
      <WifiOff className="w-3 h-3 text-red-400" />
      <span className="font-bold">DISCONNECTED</span>
    </div>
  );
};

"use client";

import React, { useState } from "react";
import { Button } from "@/components/ui/Button";
import { ConfirmDialog } from "@/components/ui/ConfirmDialog";
import { Play, Pause, SkipForward, Ban, Flag, RotateCcw } from "lucide-react";

export interface HostAuctionControlsProps {
  hasActivePlayer: boolean; hasBid: boolean; synced: boolean; canRecall: boolean; onRecall: () => void;
  isPaused: boolean;
  onPause: () => void;
  onResume: () => void;
  onSkip: () => void;
  onEnd: () => void;
}

export const HostAuctionControls: React.FC<HostAuctionControlsProps> = ({
  hasActivePlayer, hasBid, synced, canRecall, onRecall,
  isPaused,
  onPause,
  onResume,
  onSkip,
  onEnd,
}) => {
  const [confirmSkipOpen, setConfirmSkipOpen] = useState(false);
  const [confirmEndOpen, setConfirmEndOpen] = useState(false);

  return (
    <div className="flex items-center justify-between gap-2 p-2.5 rounded-xl bg-[#080a0f] border border-[#242c3d] text-xs">
      <div className="flex items-center gap-2">
        <span className="text-[10px] font-black uppercase tracking-widest text-[#00ff87] bg-[#00ff87]/15 px-2 py-0.5 rounded border border-[#00ff87]/30">
          HOST CONTROLS
        </span>
      </div>

      <div className="flex items-center gap-2 flex-wrap">
        {isPaused ? (
          <Button
            variant="stadium"
            size="sm"
            onClick={onResume}
            disabled={!synced}
            leftIcon={<Play className="w-3.5 h-3.5 fill-current" />}
          >
            Resume Auction
          </Button>
        ) : (
          <Button
            variant="secondary"
            size="sm"
            onClick={onPause}
            disabled={!synced}
            leftIcon={<Pause className="w-3.5 h-3.5" />}
          >
            Pause
          </Button>
        )}

        <Button
          variant="secondary"
          size="sm"
          onClick={() => hasActivePlayer ? setConfirmSkipOpen(true) : onSkip()}
          disabled={!synced || isPaused || hasBid}
          leftIcon={<SkipForward className="w-3.5 h-3.5" />}
        >
          {hasActivePlayer ? "Mark Unsold" : "Next Player"}
        </Button>

        {canRecall && <Button variant="secondary" size="sm" disabled={!synced || isPaused} onClick={onRecall}>Recall Unsold</Button>}
        <Button
          variant="danger"
          size="sm"
          onClick={() => setConfirmEndOpen(true)}
          disabled={!synced}
          leftIcon={<Flag className="w-3.5 h-3.5" />}
        >
          End Auction
        </Button>
      </div>

      {/* Confirmation Dialog for Skipping */}
      <ConfirmDialog
        isOpen={confirmSkipOpen}
        onClose={() => setConfirmSkipOpen(false)}
        onConfirm={() => {
          onSkip();
          setConfirmSkipOpen(false);
        }}
        title="Mark Player Unsold & Skip?"
        message="Are you sure you want to skip this player? They will be immediately moved to the Unsold / Recall pot."
        confirmLabel="Skip Player"
      />

      {/* Confirmation Dialog for Ending Auction */}
      <ConfirmDialog
        isOpen={confirmEndOpen}
        onClose={() => setConfirmEndOpen(false)}
        onConfirm={() => {
          onEnd();
          setConfirmEndOpen(false);
        }}
        title="End Entire Auction?"
        message="Are you sure you want to conclude this auction room? All participants will be redirected to the post-auction Results room."
        confirmLabel="End Auction Now"
        variant="danger"
      />
    </div>
  );
};

"use client";

import React, { useState } from "react";
import { Player, PotCategory } from "@/types";
import { Badge } from "@/components/ui/Badge";
import { formatCr } from "@/lib/utils";
import { CheckCircle2, PlayCircle, Clock, Search, Layers } from "lucide-react";

export interface PlayerPoolSidebarProps {
  players: Player[];
  activePlayerId?: string;
  currentPot: PotCategory;
}

export const PlayerPoolSidebar: React.FC<PlayerPoolSidebarProps> = ({
  players,
  activePlayerId,
  currentPot,
}) => {
  const [selectedPot, setSelectedPot] = useState<PotCategory | "all">("all");
  const [searchQuery, setSearchQuery] = useState("");

  const potCategories = [{ id: "all", label: "All Pots" }, ...Array.from(new Set(players.map(p => p.pot))).map(id => ({id, label: id}))];

  const filteredPlayers = players.filter((p) => {
    const matchesPot = selectedPot === "all" || p.pot === selectedPot;
    const matchesSearch =
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.club.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.position.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesPot && matchesSearch;
  });

  const soldCount = players.filter((p) => p.status === "sold").length;
  const totalCount = players.length;

  return (
    <div className="flex flex-col h-full bg-[#0e121a] rounded-2xl border border-[#242c3d] p-3 text-[#f8fafc] shadow-lg">
      {/* Header */}
      <div className="flex items-center justify-between pb-3 border-b border-[#242c3d]">
        <div className="flex items-center gap-2">
          <Layers className="w-4 h-4 text-[#00ff87]" />
          <h3 className="text-xs font-bold uppercase tracking-wider text-[#f8fafc]">
            POT & PLAYER POOL
          </h3>
        </div>
        <span className="text-[11px] font-mono text-[#00ff87] bg-[#00ff87]/10 px-2 py-0.5 rounded border border-[#00ff87]/20">
          {soldCount} / {totalCount} SOLD
        </span>
      </div>

      {/* Pot Selector Buttons */}
      <div className="flex items-center gap-1 overflow-x-auto py-2.5 scrollbar-none border-b border-[#242c3d]/60">
        {potCategories.map((cat) => (
          <button
            key={cat.id}
            onClick={() => setSelectedPot(cat.id)}
            className={`px-2 py-1 text-[11px] font-semibold rounded-md shrink-0 transition-colors select-none ${
              selectedPot === cat.id
                ? "bg-[#00ff87] text-[#08090d] font-bold"
                : "bg-[#151a24] text-[#94a3b8] hover:text-[#f8fafc] hover:bg-[#1e2433]"
            }`}
          >
            {cat.label}
          </button>
        ))}
      </div>

      {/* Search Input */}
      <div className="relative my-2">
        <input
          type="text"
          placeholder="Filter players by name or club..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full rounded-lg bg-[#151a24] border border-[#242c3d] px-8 py-1.5 text-xs text-[#f8fafc] placeholder-[#64748b] outline-none focus:border-[#00ff87]"
        />
        <Search className="w-3.5 h-3.5 absolute left-2.5 top-1/2 -translate-y-1/2 text-[#64748b]" />
        {searchQuery && (
          <button
            onClick={() => setSearchQuery("")}
            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-[#64748b] text-xs hover:text-white"
          >
            ✕
          </button>
        )}
      </div>

      {/* Players List */}
      <div className="flex-1 overflow-y-auto space-y-1.5 pr-1 mt-1">
        {filteredPlayers.length === 0 ? (
          <p className="text-center text-xs text-[#64748b] py-8">
            No players found in this category.
          </p>
        ) : (
          filteredPlayers.map((player) => {
            const isLive = player.id === activePlayerId || player.status === "live";
            const isSold = player.status === "sold";
            const isUnsold = player.status === "unsold";

            return (
              <div
                key={player.id}
                className={`flex items-center justify-between p-2 rounded-xl border transition-all text-xs ${
                  isLive
                    ? "bg-[#00ff87]/15 border-[#00ff87] shadow-[0_0_15px_rgba(0,255,135,0.15)]"
                    : isSold
                    ? "bg-[#151a24]/60 border-[#242c3d]/40 opacity-75"
                    : "bg-[#151a24] border-[#242c3d] hover:border-[#37435e]"
                }`}
              >
                <div className="flex items-center gap-2 truncate">
                  {isLive ? (
                    <PlayCircle className="w-3.5 h-3.5 text-[#00ff87] animate-pulse shrink-0" />
                  ) : isSold ? (
                    <CheckCircle2 className="w-3.5 h-3.5 text-slate-500 shrink-0" />
                  ) : (
                    <Clock className="w-3.5 h-3.5 text-[#64748b] shrink-0" />
                  )}

                  <div className="flex flex-col truncate">
                    <span
                      className={`font-semibold truncate ${
                        isLive ? "text-[#00ff87] font-bold" : "text-[#f8fafc]"
                      }`}
                    >
                      {player.name}
                    </span>
                    <span className="text-[10px] text-[#64748b] truncate">
                      {player.club} • {player.subPosition || player.position}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-1.5 shrink-0 ml-2">
                  <Badge variant="position" position={player.position} size="sm">
                    {player.ovr}
                  </Badge>

                  {isLive && (
                    <span className="bg-[#00ff87] text-[#08090d] font-black text-[9px] px-1.5 py-0.5 rounded uppercase tracking-wider animate-pulse">
                      LIVE
                    </span>
                  )}

                  {isSold && (
                    <span className="text-[10px] font-mono font-semibold text-amber-400">
                      {formatCr(player.soldPrice || 0)}
                    </span>
                  )}

                  {!isLive && !isSold && (
                    <span className="text-[10px] font-mono text-[#64748b]">
                      {formatCr(player.basePrice)}
                    </span>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

